let TREATMENTS=[{id:"prod_shampoo",name:"Heal Root Herbal Shampoo",price:350,desc:"Natural scalp healing & hair strengthening with Bhringraj, Neem & Brahmi (500 ml).",day:"Hair Care",image:"assets/images/products/shampoo_product_jpg_1772792947462.png"},{id:"prod_oil",name:"Hope & Heal Hair Oil",price:200,desc:"Ayurvedic blend for hair growth & deep nourishment with 12 herbs (100 ml).",day:"Hair Care",image:"assets/images/products/hair_oil_product_jpg_1772792969625.png"},{id:"prod_soap",name:"Neem & Aloe Spark Soap Bar",price:60,desc:"Deeply refreshing herbal bathing bar. Neem + Aloe Vera for clear, healthy skin (100g).",day:"Skin Care",image:null}];async function loadTreatments(){const e=document.getElementById("treatments-container");if(e){try{const e="localhost"===window.location.hostname?"http://localhost:3001":"",a=await fetch(`${e}/api/products`),t=await a.json();t&&t.products&&t.products.length>0&&(TREATMENTS=t.products.map(e=>({id:e.ID,name:e.Name,price:parseFloat(e.Price),desc:e.Description,day:e.Category||"Product",image:e.ImageURL||null})),window.TREATMENTS=TREATMENTS)}catch(e){console.info("[HopeHeal] Using static product catalogue.")}renderTreatments(e)}}function renderTreatments(e){TREATMENTS&&0!==TREATMENTS.length?(e.innerHTML=TREATMENTS.map(e=>{const a=!!(window.getCart?window.getCart():[]).find(a=>a.id===e.id),t=e.image?`<img class="product-img" src="${e.image}" alt="${e.name}" loading="lazy">`:'<div class="product-img-placeholder">🌿</div>',d={"Hair Care":"#5c6a00","Skin Care":"#1a6a5a",Supplement:"#6a3a00",Product:"#4a5030"}[e.day]||"#4a5030";return`\n            <div class="product-card${a?" selected":""}"\n                 data-id="${e.id}"\n                 onclick="addToCart('${e.id}')">\n                ${a?'<div class="selected-badge">✓ In Cart</div>':""}\n                <div class="product-img-wrap">${t}</div>\n                <div class="product-body">\n                    <div class="product-cat" style="color:${d};">${e.day}</div>\n                    <div class="product-name">${e.name}</div>\n                    <div class="product-desc">${e.desc}</div>\n                    <div class="product-footer">\n                        <div class="product-price">₹${e.price}<span class="product-price-note"> incl. taxes</span></div>\n                        <button class="btn-add${a?" btn-add-selected":""}" type="button">\n                            ${a?"✓ Added":"+ Add"}\n                        </button>\n                    </div>\n                </div>\n            </div>\n        `}).join(""),e.querySelectorAll(".product-img").forEach(e=>{e.addEventListener("error",function(){this.parentElement.innerHTML='<div class="product-img-placeholder">🌿</div>'})})):e.innerHTML='\n            <div class="col-12 text-center py-5">\n                <p class="text-muted">No products found. Please check back soon.</p>\n            </div>'}window.TREATMENTS=TREATMENTS,document.addEventListener("DOMContentLoaded",()=>{loadTreatments()}),window.renderTreatments=renderTreatments;